// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;

    function setUp() public { c = new Reentrancy_bonus(); }

    function testFuzz_property(address recipient, uint256 funding) public {
        // recipient is an admissible actor (EOA is fine: the low-level call succeeds)
        vm.assume(recipient != address(0) && recipient != address(c) && recipient != address(this));
        // fund c so the ETH transfers in withdrawReward succeed
        funding = bound(funding, 1000 ether, 10_000 ether);
        vm.deal(address(c), funding);

        // create a pending reward for the recipient
        c.getFirstWithdrawalBonus(recipient);

        // first payout drains the pending reward
        c.withdrawReward(recipient);
        uint256 balBefore = address(c).balance;

        // RULE: with rewards already zeroed, a repeated withdrawReward(r)
        // transfers 0 wei, so c's balance is unchanged.
        c.withdrawReward(recipient);

        assertTrue(address(c).balance == balBefore);
    }
}
